{"command":"cat << 'EOF' > src/fsm/context.tsx
import React, { createContext, useContext, useState, ReactNode, useEffect } from 'react';
import { FsmState, initialFsmState } from './engine';

type FsmContextType = {
  state: FsmState;
  setState: React.Dispatch<React.SetStateAction<FsmState>>;
  currentPage: string;
  setCurrentPage: React.Dispatch<React.SetStateAction<string>>;
};

const FsmContext = createContext<FsmContextType | undefined>(undefined);

export const FsmProvider = ({ children }: { children: ReactNode }) => {
  const [state, setState] = useState<FsmState>(initialFsmState);
  const [currentPage, setCurrentPage] = useState<string>('HOME');

  useEffect(() => {
    // Load mock data on mount
    fetch('/mock_data.json')
      .then((res) => res.json())
      .then((data) => {
        setState((prev) => ({
          ...prev,
          posts: data.posts,
          drafts: data.drafts,
        }));
      });
  }, []);

  return (
    <FsmContext.Provider value={{ state, setState, currentPage, setCurrentPage }}>
      {children}
    </FsmContext.Provider>
  );
};

export const useFsm = () => {
  const context = useContext(FsmContext);
  if (!context) {
    throw new Error('useFsm must be used within an FsmProvider');
  }
  return context;
};
EOF
"}

