import { CommentPostedSuccess } from './pages/CommentPostedSuccessPage';
import { FollowSuccess } from './pages/FollowSuccessPage';
import { ExploreList } from './pages/ExploreListPage';
import { Header } from './components/Header';

const AppContent = () => {
  const { currentPage } = useFsm();

  return (
    <div className="min-h-screen bg-[#FAFAFA] text-[#111] font-sans">
      {currentPage !== 'HOME' && <Header />}
      <main className="container mx-auto px-4 py-8 max-w-4xl">
