        {currentPage === 'SCHEDULE_POST' && <SchedulePost />}
        {currentPage === 'POST_SCHEDULED_SUCCESS' && <PostScheduledSuccess />}
        {currentPage === 'DRAFTS_LIST' && <DraftsList />}
        {currentPage === 'EDIT_POST' && <EditPost />}
        {currentPage === 'DRAFT_SAVED_SUCCESS' && <DraftSavedSuccess />}
        {currentPage === 'AUTHOR_PROFILE' && <AuthorProfile />}
