        {currentPage === 'FOLLOW_SUCCESS' && <FollowSuccess />}
        {currentPage === 'EXPLORE_LIST' && <ExploreList />}
      </main>
    </div>
  );
};

export default function App() {
  return (
    <FsmProvider>
      <AppContent />
    </FsmProvider>
  );
}
