          </p>
          <button
            id="permission-location-allow"
            onClick={() => setState(prev => ({ ...prev, location_permission_granted: true }))}
            className="w-full bg-black hover:bg-gray-800 text-white font-medium py-3 px-6 rounded-full transition-colors"
          >
            Allow Location Access
          </button>
        </div>
      </div>
    );
  }

  const handleSearch = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      const match = state.posts?.find(p => p.title.toLowerCase().includes(searchQuery.toLowerCase()));
      if (match) {
        setState(prev => ({
          ...prev,
          matched_post_id: match.id,
          posts_list_has_searched: true
        }));
      }
    }
  };

  const handleDragDown = () => {
    if (state.posts && state.posts.length > 0) {
      setState(prev => ({
        ...prev,
        posts_list_viewport_anchor_id: state.posts![0].id
      }));
    }
  };

  return (
    <div className="max-w-3xl mx-auto animate-in fade-in">
      <div className="flex items-center justify-between mb-12">
        <h1 className="text-4xl font-serif font-black tracking-tight text-gray-900">Latest Reads</h1>
        <button
          id="back-home"
          onClick={() => setCurrentPage('HOME')}
          className="text-sm font-medium text-gray-500 hover:text-black transition-colors"
        >
          ← Home
        </button>
      </div>

      <div className="mb-12 relative group">
        <div className="absolute inset-y-0 left-4 flex items-center pointer-events-none">
          <svg className="w-5 h-5 text-gray-400 group-focus-within:text-black transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>
        <input
          id="posts-search-input"
          type="text"
          placeholder="Search by title..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          onKeyDown={handleSearch}
          className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-full focus:ring-2 focus:ring-black focus:bg-white transition-all text-lg placeholder-gray-400"
        />
      </div>

      <div 
        id="posts-list" 
        className="space-y-12"
        onDragEnd={handleDragDown}
        draggable
      >
        {state.posts?.map(post => {
          const isMatched = state.posts_list_has_searched && state.matched_post_id === post.id;
          const isVisible = state.posts_list_viewport_anchor_id === post.id;

          return (
            <article 
              key={post.id}
              className={`group cursor-pointer border-b border-gray-100 pb-12 last:border-0 ${isMatched ? 'row-matched' : ''} ${isVisible ? 'row-visible' : ''}`}
              onClick={() => {
                if (isMatched) {
                  setState(prev => ({
                    ...prev,
                    selected_post_id: post.id,
                    posts_list_has_searched: false
                  }));
                  setCurrentPage('POST_DETAIL');
                } else if (isVisible) {
                  setState(prev => ({
                    ...prev,
                    selected_post_id: post.id,
                    posts_list_viewport_anchor_id: null
                  }));
                  setCurrentPage('POST_DETAIL');
                } else {
                  // Fallback for normal click if not strictly following the complex precondition,
                  // but FSM demands opening any post from a scrolled state.
                  // Setting anchor id directly here for UX if they just click.
                  setState(prev => ({
                    ...prev,
                    selected_post_id: post.id,
                    posts_list_viewport_anchor_id: null
                  }));
                  setCurrentPage('POST_DETAIL');
                }
              }}
            >
              <div className="flex items-center space-x-2 mb-3">
                <div className="w-6 h-6 bg-gray-200 rounded-full flex items-center justify-center text-xs font-bold text-gray-600">
                  {post.authorName[0]}
                </div>
                <span className="text-sm font-medium text-gray-900">{post.authorName}</span>
                <span className="text-gray-300">•</span>
                <span className="text-sm text-gray-500">{new Date(post.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}</span>
              </div>

              <h2 className="text-2xl font-bold font-serif text-gray-900 mb-2 group-hover:text-gray-600 transition-colors line-clamp-2">
                {post.title}
              </h2>

              <p className="text-gray-600 mb-4 line-clamp-3 leading-relaxed">
                {post.excerpt}
              </p>

              <div className="flex items-center justify-between">
                <div className="flex space-x-2">
                  {post.tags.map((tag: string) => (
                    <span key={tag} className="px-3 py-1 bg-gray-100 text-gray-600 text-xs rounded-full font-medium">
                      {tag}
                    </span>
                  ))}
                </div>
                <span className="text-sm text-gray-400 font-medium">5 min read</span>
              </div>
            </article>
          );
        })}
        {(!state.posts || state.posts.length === 0) && (
          <div className="text-center py-20 text-gray-500 font-medium">No posts available.</div>
        )}
      </div>
    </div>
  );
};
