import React, { useState } from 'react';
import { useFsm } from '../fsm/context';

export const CreatePost = () => {
  const { state, setState, setCurrentPage } = useFsm();
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [visibilityOpen, setVisibilityOpen] = useState(false);

  const handleTypeTitle = (e: React.ChangeEvent<HTMLInputElement>) => {
    setTitle(e.target.value);
    setState(prev => ({ ...prev, new_post_title: 'typed' }));
  };

  const handleTypeBody = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setBody(e.target.value);
    setState(prev => ({ ...prev, new_post_body: 'typed' }));
  };

  const isFormValid = state.new_post_title && state.new_post_body;

  const handleSaveDraft = () => {
    if (isFormValid) {
      const newDraft = {
        id: `draft-${Date.now()}`,
        title: title,
        body: body,
        date: new Date().toISOString()
      };

      setState(prev => ({
        ...prev,
        drafts: [...(prev.drafts || []), newDraft]
      }));
      setCurrentPage('DRAFT_SAVED_SUCCESS');
    }
