          drafts_list_has_searched: true
        }));
      }
    }
  };

  const handleDragDown = () => {
    if (state.drafts && state.drafts.length > 0) {
      setState(prev => ({
        ...prev,
        drafts_list_viewport_anchor_id: state.drafts![0].id
      }));
    }
  };

  return (
    <div className="max-w-3xl mx-auto animate-in fade-in">
      <div className="flex items-center justify-between mb-12">
        <h1 className="text-4xl font-serif font-black tracking-tight text-gray-900">Your Drafts</h1>
        <button
          id="back-home"
          onClick={() => setCurrentPage('HOME')}
          className="text-sm font-medium text-gray-500 hover:text-black transition-colors"
        >
          ← Home
        </button>
      </div>

      <div className="mb-12 relative group">
        <div className="absolute inset-y-0 left-4 flex items-center pointer-events-none">
          <svg className="w-5 h-5 text-gray-400 group-focus-within:text-black transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>
        <input
          id="drafts-search-input"
          type="text"
          placeholder="Search drafts..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          onKeyDown={handleSearch}
          className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-full focus:ring-2 focus:ring-black focus:bg-white transition-all text-lg placeholder-gray-400"
        />
      </div>

      <div 
        id="drafts-list" 
        className="space-y-6"
        onDragEnd={handleDragDown}
        draggable
      >
        {state.drafts?.map(draft => {
          const isMatched = state.drafts_list_has_searched && state.matched_draft_id === draft.id;
          const isVisible = state.drafts_list_viewport_anchor_id === draft.id;

          return (
            <article 
              key={draft.id}
              className={`group cursor-pointer bg-white p-6 rounded-2xl border border-gray-100 shadow-sm hover:shadow-md transition-all ${isMatched ? 'row-matched ring-2 ring-[#1A8917]' : ''} ${isVisible ? 'row-visible' : ''}`}
              onClick={() => {
                if (isMatched) {
                  setState(prev => ({
                    ...prev,
                    selected_draft_id: draft.id,
                    drafts_list_has_searched: false,
                    edit_title: draft.title,
                    edit_body: draft.body
                  }));
                  setCurrentPage('EDIT_POST');
                } else if (isVisible) {
                  setState(prev => ({
                    ...prev,
                    selected_draft_id: draft.id,
                    drafts_list_viewport_anchor_id: null,
                    edit_title: draft.title,
                    edit_body: draft.body
                  }));
                  setCurrentPage('EDIT_POST');
                } else {
                  setState(prev => ({
                    ...prev,
                    selected_draft_id: draft.id,
                    edit_title: draft.title,
                    edit_body: draft.body
                  }));
                  setCurrentPage('EDIT_POST');
                }
              }}
            >
              <h2 className="text-xl font-bold font-serif text-gray-900 mb-2 group-hover:text-[#1A8917] transition-colors">
                {draft.title || 'Untitled Draft'}
              </h2>

              <p className="text-gray-500 mb-4 line-clamp-2 text-sm leading-relaxed">
                {draft.body || 'No content yet...'}
              </p>

              <div className="flex items-center text-xs font-medium text-gray-400">
                 Last edited: {new Date(draft.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}
              </div>
            </article>
          );
        })}
        {(!state.drafts || state.drafts.length === 0) && (
